        continue

    if inspect.isfunction(val) and val.__doc__ is None:
        doc = find_docstring(key, None)
        if doc is not None:
            val.__doc__ = doc
    elif isinstance(val, property):
        # A property's __doc__ is a copy of the getter's docstring
        # made at creation time, so it has to be updated separately.
        for attribute in ('fget', 'fset', 'fdel'):
            func = getattr(val, attribute, None)
