def _split_field_arg(fieldarg: str) -> Tuple[str, str]:
    """Split a typed field argument into ``(type, name)``.

    The type may itself contain whitespace (for example ``dict(str, str)``),
    so a naive split on the first whitespace is not sufficient.  Instead, we
    split on the first whitespace that is not enclosed in brackets.
